function validate([arr, target]) {
  if (!Array.isArray(arr) || arr.length < 1 || arr.length > 100000) return 'arr needs 1 to 10^5 values.';
  if (arr.some(v => !Number.isInteger(v) || v < 1 || v > 1000000)) return 'Each arr[i] is an integer from 1 to 10^6.';
  if (!Number.isInteger(target) || target < 0 || target > 10000000) return 'target is an integer from 0 to 10^7.';
  return null;
}

