function closestToTarget(arr, target) {
  let best = Infinity;
  let ands = [];
  for (const value of arr) {
    const next = [value];
    for (const prev of ands) {
      const merged = prev & value;
      if (merged !== next[next.length - 1]) {
        next.push(merged);
      }
    }
    for (const result of next) {
      best = Math.min(best, Math.abs(result - target));
    }
    ands = next;
  }
  return best;
}

