function closestToTarget(arr, target) {
  // Try every pair l <= r, recomputing the AND from scratch (r < l only gives -10^9, which never wins).
  let best = Infinity;
  for (let l = 0; l < arr.length; l++) {
    for (let r = l; r < arr.length; r++) {
      let and = arr[l];
      for (let i = l + 1; i <= r; i++) and = and & arr[i];
      best = Math.min(best, Math.abs(and - target));
    }
  }
  return best;
}

