function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const style = pick(4);
  const n = size === 'large' ? 1500 + pick(501) : 1 + pick(10);
  const bits = size === 'large' ? 20 : 3 + pick(4);
  const limit = Math.min(1000000, 2 ** bits - 1);
  const make = () => {
    if (style === 0) return 1 + pick(limit);
    // Dense values that lose only a few bits keep long ANDs non-zero and varied.
    let value = limit;
    const drops = 1 + pick(style === 1 ? 2 : 4);
    for (let k = 0; k < drops; k++) value &= ~(1 << pick(bits));
    if (style === 3 && rand() < 0.3) value = 1 << pick(bits);
    return Math.min(1000000, Math.max(1, value));
  };
  const arr = Array.from({ length: n }, make);
  const roll = rand();
  let target;
  if (roll < 0.2) target = 0;
  else if (roll < 0.35) target = pick(10000001);
  else if (roll < 0.6) target = arr[pick(n)] + pick(5) - 2;
  else target = pick(limit + 2);
  return [arr, Math.max(0, target)];
}
